#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets up the team Gmail account that sends every email the app sends. Rerun it when the app
# password stops working, which happens whenever the account's password changes.

TOTAL_STAGES=6

# Run from the repo root, wherever the wizard is started from.
cd "$(dirname "$0")/.."
ENV_FILE=".env.local"
PURGE_DIR="scripts/gmail-purge"
VERCEL_ENV_URL="https://vercel.com/kqw/qloo-hackathon/settings/environment-variables"

# Files holding the app password go in a private folder that's removed on any exit, Ctrl-C too.
umask 077
WORK_DIR=$(mktemp -d)
trap 'rm -rf "$WORK_DIR"' EXIT

# On Git Bash the library's open_url falls through to explorer.exe, which exits 1 even when the
# page opens, so it would warn at every stage. Windows' URL handler opens it and exits 0.
if [[ "$(uname -s)" == MINGW* || "$(uname -s)" == MSYS* ]]; then
  open_url() {
    printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$1"
    rundll32.exe url.dll,FileProtocolHandler "$1" >/dev/null 2>&1 ||
      warn "couldn't open a browser, so visit it manually: $1"
  }
fi

# clipboard < INPUT puts its input on the clipboard, and fails when there's no clipboard tool.
clipboard() {
  if   command -v clip.exe >/dev/null 2>&1; then clip.exe
  elif command -v pbcopy   >/dev/null 2>&1; then pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then wl-copy
  elif command -v xclip    >/dev/null 2>&1; then xclip -selection clipboard
  else return 1; fi
}

# copy_to_clipboard FILE puts a file on the clipboard, or says to copy it by hand.
copy_to_clipboard() {
  if clipboard < "$1"; then
    printf '  %s✓ copied%s %s to the clipboard\n' "$GREEN" "$RESET" "$1"
  else
    warn "couldn't reach the clipboard, so copy $1 by hand"
  fi
}

ask_gmail_user() {
  while :; do
    ask GMAIL_USER "The account's address (name@gmail.com):"
    [[ "$GMAIL_USER" =~ ^[^@+[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$ ]] && break
    warn "That doesn't look like an email address without a +tag."
  done
  write_env GMAIL_USER "$GMAIL_USER"
}

ask_app_password() {
  while :; do
    ask_secret GMAIL_APP_PASSWORD "Paste the app password (hidden):"
    GMAIL_APP_PASSWORD="${GMAIL_APP_PASSWORD// /}" # Google shows it in groups of four
    [[ "$GMAIL_APP_PASSWORD" =~ ^[a-z]{16}$ ]] && break
    warn "An app password is 16 letters. Paste it again."
  done
  write_env GMAIL_APP_PASSWORD "$GMAIL_APP_PASSWORD"
}

# send_test_email TO signs in to Gmail's SMTP server with the app password, as the app will, and
# sends one email to TO.
send_test_email() {
  local to="$1" status=0
  printf 'From: Outfit Recommender <%s>\r\nTo: <%s>\r\nSubject: Outfit Recommender SMTP check\r\n\r\nThe team Gmail sends over SMTP, and mail to the +demo address arrives.\r\nThe daily purge deletes the copy in Sent after a day.\r\n' \
    "$GMAIL_USER" "$to" > "$WORK_DIR/message"
  # The credentials reach curl through a config file, so they never show in the process list.
  printf 'user = "%s:%s"\n' "$GMAIL_USER" "$GMAIL_APP_PASSWORD" > "$WORK_DIR/curl-config"
  curl --silent --show-error --url "smtps://smtp.gmail.com:465" --config "$WORK_DIR/curl-config" \
    --mail-from "$GMAIL_USER" --mail-rcpt "$to" --upload-file "$WORK_DIR/message" || status=$?
  rm -f "$WORK_DIR/curl-config"
  return "$status"
}

banner "Team Gmail setup"

stage "Create the team Gmail account"
say "This throwaway account sends every email the app sends. If it already exists, just enter its address."
open_url "https://accounts.google.com/signup"
step "Create a personal Gmail account named \"Outfit Recommender\". Google may ask for a phone number."
step "Keep its password in the team's password manager, never in the repo."
step "Add a teammate's phone or email for recovery, so nobody gets locked out."
ask_gmail_user

stage "Turn on 2-Step Verification"
say "Google only gives app passwords to accounts with 2-Step Verification on."
open_url "https://myaccount.google.com/signinoptions/twosv?authuser=$GMAIL_USER"
step "Check that the avatar in the top-right corner is $GMAIL_USER. If it isn't, switch accounts."
step "Turn on 2-Step Verification and follow Google's steps."
step "Pick a second step the whole team can reach, such as backup codes kept in the password manager."
pause "Press Enter once 2-Step Verification is on."

stage "Create an app password"
say "The app signs in to Gmail with this, never with the account's password."
open_url "https://myaccount.google.com/apppasswords?authuser=$GMAIL_USER"
step "Name it \"Outfit Recommender SMTP\" and click Create."
step "Copy the 16-letter password. Google shows it only once."
note "If Google says the setting isn't available, 2-Step Verification isn't on yet."
warn "It stops working whenever the account's password changes. Rerun this wizard if that happens."
ask_app_password

stage "Send a test email to the +demo address"
DEMO_EMAIL="${GMAIL_USER%@*}+demo@${GMAIL_USER#*@}"
say "This sends one email over SMTP with the app password, the way the app will, to $DEMO_EMAIL."
say "The Demo Account uses that address, so its password resets reach the team."
pause "Press Enter to send it."
sent=yes
until send_test_email "$DEMO_EMAIL"; do
  warn "Gmail didn't take it. The app password is usually wrong, or 2-Step Verification is off."
  if ! confirm "Paste the app password again and retry?"; then
    sent=no
    SKIPPED+=("Send a test email over SMTP to $DEMO_EMAIL")
    break
  fi
  ask_app_password
done
if [[ "$sent" == yes ]]; then
  printf '  %s✓ sent%s to %s\n' "$GREEN" "$RESET" "$DEMO_EMAIL"
  open_url "https://mail.google.com/mail/?authuser=$GMAIL_USER"
  step "Look in the Inbox for \"Outfit Recommender SMTP check\"."
  confirm "Did it arrive in the Inbox?" ||
    SKIPPED+=("Confirm mail to $DEMO_EMAIL arrives in the Inbox (if it's only in Sent, the Demo Account's resets will be too)")
fi

stage "Add the variables to Vercel"
say "Production only, since Preview has no database yet."
[[ "$sent" == yes ]] || warn "The test email didn't go out, so this app password may not work on Vercel either."
open_url "$VERCEL_ENV_URL"
step "Add GMAIL_USER = $GMAIL_USER"
step "Add GMAIL_APP_PASSWORD = the app password"
step "For both: Production only, Sensitive on, then Save."
copied_password=no
if confirm "Copy the app password to the clipboard for this?"; then
  if printf '%s' "$GMAIL_APP_PASSWORD" | clipboard; then
    copied_password=yes
    printf '  %s✓ copied%s the app password to the clipboard\n' "$GREEN" "$RESET"
  else
    warn "couldn't reach the clipboard, so copy GMAIL_APP_PASSWORD from $ENV_FILE"
  fi
fi
note "Production picks them up at its next deploy."
pause "Press Enter once both are saved."
if [[ "$copied_password" == yes ]] && printf '' | clipboard; then
  printf '  %s✓ cleared%s the clipboard\n' "$GREEN" "$RESET"
  note "If Windows clipboard history (Win+V) is on, delete the app password there too."
  pause
fi

stage "Install the daily sent-mail purge"
say "An Apps Script project in the team account permanently deletes sent mail older than a day,"
say "every day, as the Privacy Policy promises."
warn "That's everything in Sent, the team's own replies too, such as answers to privacy requests."
open_url "https://script.google.com/home?authuser=$GMAIL_USER"
step "Check the avatar is $GMAIL_USER, click New project, and name it \"Purge sent mail\"."
step "Project Settings (gear icon): tick Show \"appsscript.json\" manifest file in editor."
pause "Press Enter to copy appsscript.json."
copy_to_clipboard "$PURGE_DIR/appsscript.json"
step "Editor (<> icon): open appsscript.json, replace everything with the clipboard, and save."
pause "Press Enter to copy Code.gs."
copy_to_clipboard "$PURGE_DIR/Code.gs"
step "Open Code.gs, replace everything with the clipboard, and save."
step "Pick installTrigger in the function menu above the code, click Run, and allow access."
note "Google says it hasn't verified the app, since it's the account's own script: click Advanced, then"
note "Go to Purge sent mail. It asks to permanently delete email, which is what the purge does."
step "Pick purgeSentMail and click Run. The log says how many it deleted, and 0 is fine on day one."
step "Triggers (clock icon) should list one purgeSentMail trigger: time-based, every day."
confirm "Is the trigger listed?" || SKIPPED+=("Install the Apps Script purge trigger")

finish
